const all = yield* Database.query(Filter.type(types['com.example.type.task'])).run;
yield* print('total tasks', all.length);
const docs = all.filter(t => (t.title ?? '').toLowerCase().includes('docs'));
yield* print('docs matches', JSON.stringify(docs.map(t => ({ title: t.title, status: t.status }))));
for (const t of docs) { Obj.update(t, (x) => { x.status = 'done'; }); }
yield* Database.flush();
const after = yield* Database.query(Filter.type(types['com.example.type.task'])).run;
yield* print('done total', after.filter(t => t.status === 'done').length);
yield* print('statuses', JSON.stringify(after.map(t => ({ title: t.title, status: t.status }))));
